#include <omp.h>
#include <cstddef>
#include <limits>
#include <string>
#include <vector>

using std::size_t;

struct Book {
    std::string title;
    int pages;
};

size_t findLastShortBook(std::vector<Book> const& books) {
    const long long n = static_cast<long long>(books.size());

    // Store (index + 1) so that 0 can mean "not found".
    long long best_plus_one = 0;

    #pragma omp parallel for reduction(max : best_plus_one)
    for (long long i = 0; i < n; ++i) {
        if (books[static_cast<size_t>(i)].pages < 100) {
            const long long candidate = i + 1;
            if (candidate > best_plus_one) {
                best_plus_one = candidate;
            }
        }
    }

    if (best_plus_one == 0) {
        return std::numeric_limits<size_t>::max(); // not found
    }

    return static_cast<size_t>(best_plus_one - 1);
}
